CREATE COLUMN TABLE "TEST_AP"."OUNCL" ("AbsEntry" INTEGER CS_INT NOT NULL , "Codelist" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(20) NOT NULL , "Descrip" NVARCHAR(254), "SchemaCode" NVARCHAR(20) DEFAULT ' ' NOT NULL , "SchemaDesc" NVARCHAR(254), "LogInstanc" INTEGER CS_INT DEFAULT 0, "UpdateDate" LONGDATE CS_LONGDATE, "UserSign" SMALLINT CS_INT, "UserSign2" SMALLINT CS_INT, "IsDefault" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OUNCL_Code" ON "TEST_AP"."OUNCL" ( "Codelist" ASC, "Code" ASC, "SchemaCode" ASC );
CREATE INDEX "OUNCL_IsDefault" ON "TEST_AP"."OUNCL" ( "IsDefault" ASC )